// Package tbls reads schema.json generated by tbls (https://github.com/k1LoW/tbls)
// and converts it into dbfolio's internal model.
package tbls

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/onozaty/dbfolio/internal/schema"
)

// tblsSchema mirrors the subset of tbls schema.json that dbfolio uses.
// Unknown fields are ignored so that newer tbls versions can still be read.
type tblsSchema struct {
	Name      string          `json:"name"`
	Desc      string          `json:"desc"`
	Tables    []*tblsTable    `json:"tables"`
	Relations []*tblsRelation `json:"relations"`
	Functions []*tblsFunction `json:"functions"`
	Enums     []*tblsEnum     `json:"enums"`
	Driver    *tblsDriver     `json:"driver"`
}

type tblsFunction struct {
	Name       string `json:"name"`
	ReturnType string `json:"return_type"`
	Arguments  string `json:"arguments"`
	Type       string `json:"type"`
}

type tblsEnum struct {
	Name   string   `json:"name"`
	Values []string `json:"values"`
}

type tblsDriver struct {
	Meta *struct {
		SearchPaths []string `json:"search_paths"`
	} `json:"meta"`
}

type tblsTable struct {
	Name        string            `json:"name"`
	Type        string            `json:"type"`
	Comment     string            `json:"comment"`
	Columns     []*tblsColumn     `json:"columns"`
	Indexes     []*tblsIndex      `json:"indexes"`
	Constraints []*tblsConstraint `json:"constraints"`
	Triggers    []*tblsTrigger    `json:"triggers"`
	Def         string            `json:"def"`
	// ReferencedTables lists the tables a view reads.
	ReferencedTables []string `json:"referenced_tables"`
}

type tblsColumn struct {
	Name     string  `json:"name"`
	Type     string  `json:"type"`
	Nullable bool    `json:"nullable"`
	Default  *string `json:"default"`
	ExtraDef string  `json:"extra_def"`
	Comment  string  `json:"comment"`
}

type tblsIndex struct {
	Name    string   `json:"name"`
	Def     string   `json:"def"`
	Columns []string `json:"columns"`
	Comment string   `json:"comment"`
}

type tblsConstraint struct {
	Name              string   `json:"name"`
	Type              string   `json:"type"`
	Def               string   `json:"def"`
	ReferencedTable   *string  `json:"referenced_table"`
	Columns           []string `json:"columns"`
	ReferencedColumns []string `json:"referenced_columns"`
	Comment           string   `json:"comment"`
}

type tblsTrigger struct {
	Name    string `json:"name"`
	Def     string `json:"def"`
	Comment string `json:"comment"`
}

type tblsRelation struct {
	Table             string   `json:"table"`
	Columns           []string `json:"columns"`
	Cardinality       string   `json:"cardinality"`
	ParentTable       string   `json:"parent_table"`
	ParentColumns     []string `json:"parent_columns"`
	ParentCardinality string   `json:"parent_cardinality"`
	Def               string   `json:"def"`
	Virtual           bool     `json:"virtual"`
}

// Load reads a tbls schema.json file and converts it into the internal model.
func Load(path string) (*schema.Schema, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read schema file: %w", err)
	}
	return parse(b, "schema file "+path)
}

// Read reads tbls schema.json from r (e.g. standard input, for
// "tbls out -t json | dbfolio build -") and converts it into the internal model.
// name describes r in error messages.
func Read(r io.Reader, name string) (*schema.Schema, error) {
	b, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", name, err)
	}
	return parse(b, name)
}

// parse converts schema.json content; source describes it in error messages.
func parse(b []byte, source string) (*schema.Schema, error) {
	var s tblsSchema
	if err := json.Unmarshal(b, &s); err != nil {
		return nil, fmt.Errorf("parse %s: %w", source, err)
	}

	// tbls always emits "tables" (even when empty), so its absence means the
	// file is valid JSON but not a tbls schema.json.
	if s.Tables == nil {
		return nil, fmt.Errorf("parse %s: %w", source, ErrNotTblsSchema)
	}
	// Reject malformed input here so that rendering never fails after the
	// previous output has already been cleaned.
	if err := validate(&s); err != nil {
		return nil, fmt.Errorf("parse %s: %w", source, err)
	}

	return convert(&s), nil
}

func validate(s *tblsSchema) error {
	tables := make(map[string]*tblsTable, len(s.Tables))
	for i, t := range s.Tables {
		if t == nil {
			return fmt.Errorf("tables[%d] is null", i)
		}
		if t.Name == "" {
			return fmt.Errorf("tables[%d] has no name", i)
		}
		// Table names identify pages and relation endpoints.
		if _, ok := tables[t.Name]; ok {
			return fmt.Errorf("duplicate table name %s", t.Name)
		}
		tables[t.Name] = t
		for j, c := range t.Columns {
			if c == nil {
				return fmt.Errorf("table %s: columns[%d] is null", t.Name, j)
			}
		}
		for j, x := range t.Indexes {
			if x == nil {
				return fmt.Errorf("table %s: indexes[%d] is null", t.Name, j)
			}
		}
		for j, x := range t.Constraints {
			if x == nil {
				return fmt.Errorf("table %s: constraints[%d] is null", t.Name, j)
			}
		}
		for j, x := range t.Triggers {
			if x == nil {
				return fmt.Errorf("table %s: triggers[%d] is null", t.Name, j)
			}
		}
	}
	for i, f := range s.Functions {
		if f == nil {
			return fmt.Errorf("functions[%d] is null", i)
		}
	}
	for i, e := range s.Enums {
		if e == nil {
			return fmt.Errorf("enums[%d] is null", i)
		}
	}
	for i, r := range s.Relations {
		if r == nil {
			return fmt.Errorf("relations[%d] is null", i)
		}
		if err := validateRelation(r, tables); err != nil {
			return fmt.Errorf("relations[%d] (%s -> %s): %w", i, r.Table, r.ParentTable, err)
		}
	}
	return nil
}

// validateRelation rejects relations that cannot be linked. tbls itself checks
// these when it builds relations (including virtual ones from .tbls.yml), so a
// failure here means the file was edited or is inconsistent; skipping silently
// would produce misleading documentation.
func validateRelation(r *tblsRelation, tables map[string]*tblsTable) error {
	child, ok := tables[r.Table]
	if !ok {
		return fmt.Errorf("table %q not found", r.Table)
	}
	parent, ok := tables[r.ParentTable]
	if !ok {
		return fmt.Errorf("parent table %q not found", r.ParentTable)
	}
	if len(r.Columns) == 0 {
		return errors.New("no columns")
	}
	if len(r.Columns) != len(r.ParentColumns) {
		return fmt.Errorf("%d columns but %d parent columns", len(r.Columns), len(r.ParentColumns))
	}
	if err := checkColumns(child, r.Columns); err != nil {
		return err
	}
	return checkColumns(parent, r.ParentColumns)
}

func checkColumns(t *tblsTable, names []string) error {
	for _, n := range names {
		found := false
		for _, c := range t.Columns {
			if c.Name == n {
				found = true
				break
			}
		}
		if !found {
			return fmt.Errorf("column %q not found in table %s", n, t.Name)
		}
	}
	return nil
}

// ErrNotTblsSchema is returned when the file is JSON but lacks tbls schema fields.
var ErrNotTblsSchema = errors.New(`"tables" field not found; is this a tbls schema.json?`)

func convert(s *tblsSchema) *schema.Schema {
	out := &schema.Schema{
		Name:      s.Name,
		Desc:      s.Desc,
		Tables:    make([]*schema.Table, 0, len(s.Tables)),
		Relations: make([]*schema.Relation, 0, len(s.Relations)),
	}
	byName := make(map[string]*schema.Table, len(s.Tables))
	for _, t := range s.Tables {
		ct := convertTable(t)
		out.Tables = append(out.Tables, ct)
		byName[t.Name] = ct
	}
	for _, f := range s.Functions {
		out.Functions = append(out.Functions, &schema.Function{Name: f.Name, ReturnType: f.ReturnType, Arguments: f.Arguments, Type: f.Type})
	}
	for _, e := range s.Enums {
		out.Enums = append(out.Enums, &schema.Enum{Name: e.Name, Values: e.Values})
	}
	if s.Driver != nil && s.Driver.Meta != nil {
		out.Driver = &schema.Driver{SearchPaths: s.Driver.Meta.SearchPaths}
	}
	// validate has ensured that both endpoints exist.
	for _, r := range s.Relations {
		out.Relations = append(out.Relations, &schema.Relation{
			Table:             byName[r.Table],
			Columns:           r.Columns,
			Cardinality:       schema.Cardinality(r.Cardinality),
			ParentTable:       byName[r.ParentTable],
			ParentColumns:     r.ParentColumns,
			ParentCardinality: schema.Cardinality(r.ParentCardinality),
			Def:               r.Def,
			Virtual:           r.Virtual,
		})
	}
	return out
}

func convertTable(t *tblsTable) *schema.Table {
	out := &schema.Table{
		Name:    t.Name,
		Type:    t.Type,
		View:    isView(t.Type),
		Comment: t.Comment,
		Def:     t.Def,

		ReferencedTables: t.ReferencedTables,
	}
	for _, c := range t.Columns {
		out.Columns = append(out.Columns, &schema.Column{
			Name:     c.Name,
			Type:     c.Type,
			Nullable: c.Nullable,
			Default:  c.Default,
			ExtraDef: c.ExtraDef,
			Comment:  c.Comment,
		})
	}
	for _, x := range t.Indexes {
		out.Indexes = append(out.Indexes, &schema.Index{
			Name:    x.Name,
			Def:     x.Def,
			Columns: x.Columns,
			Comment: x.Comment,
		})
	}
	for _, x := range t.Constraints {
		kind, ok := constraintKind(x.Type)
		if !ok {
			continue
		}
		c := &schema.Constraint{
			Name:    x.Name,
			Kind:    kind,
			Type:    x.Type,
			Def:     x.Def,
			Columns: x.Columns,
			Comment: x.Comment,
		}
		if kind == schema.ConstraintForeignKey {
			if x.ReferencedTable != nil {
				c.ReferencedTable = *x.ReferencedTable
			}
			c.ReferencedColumns = x.ReferencedColumns
		}
		out.Constraints = append(out.Constraints, c)
	}
	for _, x := range t.Triggers {
		out.Triggers = append(out.Triggers, &schema.Trigger{
			Name:    x.Name,
			Def:     x.Def,
			Comment: x.Comment,
		})
	}
	return out
}

// isView covers "VIEW" and "MATERIALIZED VIEW" (PostgreSQL), "view" (SQLite), etc.
func isView(tableType string) bool {
	return strings.Contains(strings.ToUpper(tableType), "VIEW")
}

// constraintKind maps a tbls constraint type. ok is false for constraints that
// are not shown, such as PostgreSQL 18's NOT NULL constraints ("n"), which
// duplicate the column's Nullable attribute.
func constraintKind(tblsType string) (kind schema.ConstraintKind, ok bool) {
	switch strings.ToUpper(tblsType) {
	case "PRIMARY KEY":
		return schema.ConstraintPrimaryKey, true
	case "FOREIGN KEY":
		return schema.ConstraintForeignKey, true
	case "UNIQUE":
		return schema.ConstraintUnique, true
	case "CHECK":
		return schema.ConstraintCheck, true
	case "N":
		return "", false
	default:
		return schema.ConstraintOther, true
	}
}
